import React from 'react';
import ControlButton from './ControlButton.tsx';
import MuteIcon from '../../assets/icons/Mute.svg';
import MuteDarkIcon from '../../assets/icons/MuteDark.svg';
import RecordIcon from '../../assets/icons/Record.svg';
import RecordRedIcon from '../../assets/icons/RecordRed.svg';
import { useTracksContext } from '../contexts/TracksContext.tsx';

const TrackControls: React.FC<{ trackNumber: number }> = ({ trackNumber }) => {
    const { tracks, selectedTrack, setSelectedTrack, setTracks } = useTracksContext();
    const track = tracks[trackNumber];
    const { name, color } = track;

    const handleMuteClick = () => {
      setTracks(tracks.map((t, index) => 
        index === trackNumber 
          ? { ...t, isMuted: !t.isMuted }
          : t
      ));
    };

    const handleSoloClick = () => {
      setTracks(tracks.map((t, index) => {
        if (index === trackNumber) {
          // Toggle solo for clicked track and unmute it
          return { 
            ...t, 
            isSolo: !t.isSolo, 
            isMuted: false 
          };
        } else if (!track.isSolo) {
          // If enabling solo, mute all other tracks
          return { 
            ...t, 
            isSolo: false, 
            isMuted: true 
          };
        } else {
          // If disabling solo, unmute all other tracks
          return { 
            ...t, 
            isSolo: false, 
            isMuted: false 
          };
        }
      }));
    };

    return (
      <div 
        className={`flex flex-col overflow-hidden gap-1.5 items-start self-stretch border-b-2 border-r-2 border-black border-solid bg-opacity-80 ${selectedTrack === trackNumber ? 'bg-zinc-600' : 'bg-zinc-700'} w-[107px] h-[96px] `}
        onClick={() => setSelectedTrack(trackNumber)}
      >
        <div className={`overflow-hidden px-3  border-black  text-xs text-black w-[107px]`} style={{ backgroundColor: color, marginTop: '0px' }}>
          {name}
        </div>
        <div className="flex flex-col gap-2.5 px-2.5">
          <div className="flex flex-col w-full ">
            <label htmlFor={`vol-${name}`} className="text-xs text-gray-300">Vol</label>
            <input
              type="range"
              id={`vol-${name}`}
              min="0"
              max="20"
              value={track.volume}
              className="flex w-full h-2.5 bg-stone-900 appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-2.5 [&::-webkit-slider-thumb]:h-2.5 [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:rounded-full"
              aria-label={`Volume for ${name}`}
              onChange={(e) => {
                setTracks(tracks.map((t, index) =>
                  index === trackNumber
                    ? { ...t, volume: Number(e.target.value) }
                    : t
                ));
              }}
            />
          </div>
          <div className="flex justify-between items-center w-full pb-1">
            <ControlButton
              icon={MuteIcon}
              clickedIcon={MuteDarkIcon}
              height="26px"
              width="37px"
              label={false}
              onClick={handleMuteClick}
              clickedExternal={track.isMuted}
            />
            <ControlButton
              text="Solo"
              label={false}
              height="26px"
              width="37px"
              onClick={handleSoloClick}
              clickedExternal={track.isSolo}
            />
          </div>
        </div>
      </div>
    );
};

export default TrackControls;