import React, { useEffect, useRef } from 'react';
import { useTracksContext } from '../contexts/TracksContext.tsx';

interface PlaybackMarkerProps {
  width: number;
  scale: number;
  className?: string;
}

const PlaybackMarker: React.FC<PlaybackMarkerProps> = ({ width, scale, className }) => {
  const { playbackPosition } = useTracksContext();
  const markerRef = useRef<HTMLDivElement>(null);

  const position = playbackPosition * scale;

  return (
    <div 
      ref={markerRef}
      className={`relative h-full w-[2px] bg-red-500 pointer-events-none z-50 ${className || ''}`}
      style={{
        left: `${position}px`,
        transform: `translateX(-50%)`,
      }}
    >
      <div className="w-3 h-3 bg-red-500 rounded-full -translate-x-[5px]" />
    </div>
  );
};

export default PlaybackMarker;
