import React, { useState, useRef, useEffect } from 'react';
import AudioClip from './AudioClip.tsx';
import { useNavigate } from 'react-router-dom';
import { useTracksContext } from '../contexts/TracksContext.tsx';

const TrackArea: React.FC<{ trackNumber: number }> = ({ trackNumber }) => {
    const { tracks, zoomLevel, selectedTrack, setSelectedTrack, activeRecordingTrack, duration } = useTracksContext();
    const track = tracks[trackNumber];
    const { name, color, commentsPageLink   } = track;
    
    const [contextMenuVisible, setContextMenuVisible] = useState(false);
    const [contextMenuPosition, setContextMenuPosition] = useState({ x: 0, y: 0 });
    const contextMenuRef = useRef<HTMLDivElement | null>(null);
  
    const navigate = useNavigate();
  
    const handleCommentsClick = () => {
      console.log(commentsPageLink);
      navigate(commentsPageLink);
    };
  
    const handleContextMenu = (event: React.MouseEvent) => {
      event.preventDefault();
      setContextMenuPosition({ x: event.clientX, y: event.clientY });
      setContextMenuVisible(true);
    };
  
    const handleClickOutside = (event: MouseEvent) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
        setContextMenuVisible(false);
      }
    };
  
    useEffect(() => {
      document.addEventListener('click', handleClickOutside);
      return () => {
        document.removeEventListener('click', handleClickOutside);
      };
    }, []);
  
    // Use the same PIXELS_PER_SECOND constant as defined in TrackList
  
    const isRecording = trackNumber === activeRecordingTrack;
  
    return (
      <div 
        className={`flex pl-1.5 items-center h-[96px] w-[100000px] border-b-2   border-black bg-opacity-80 border-solid ${selectedTrack === trackNumber ? 'bg-zinc-700' : 'bg-neutral-800'}  ${isRecording ? 'border-l-4 border-l-red-500' : ''} relative`} 
        onContextMenu={handleContextMenu}
        onClick={() => setSelectedTrack(trackNumber)}
      >
        {contextMenuVisible && (
          <div
            ref={contextMenuRef}
            className="fixed bg-neutral-700 rounded-lg shadow-lg py-2 z-50"
            style={{
              top: contextMenuPosition.y,
              left: contextMenuPosition.x
            }}
          >
            <ul className="flex flex-col">
              <li className="px-4 py-2 text-white hover:bg-neutral-600 transition-colors cursor-pointer" onClick={handleCommentsClick}>Comment</li>
              <li className="px-4 py-2 text-white hover:bg-neutral-600 transition-colors cursor-pointer">Transpose</li>
              <li className="px-4 py-2 text-white hover:bg-neutral-600 transition-colors cursor-pointer">Enhance</li>
            </ul>
          </div>
        )}
  
        {track.clips.map((clip, index) => (
          <AudioClip 
            key={index} 
            audioUrl={clip.audioUrl} 
            trackName={name} 
            recordingDate={clip.recordingDate} 
            isMuted={track.isMuted} 
            volume={track.volume} 
            color={color}
            start={clip.start}
            length={clip.length}
            scale={zoomLevel}
            isPlaying={clip.isPlaying}
          />
        ))} 
      </div>
    );
  };
  
export default TrackArea;