import React, { useState, useEffect } from 'react';

interface ControlButtonProps {
  icon?: string;
  clickedIcon?: string;
  clickedColor?: string;
  backgroundColor?: string;
  onClick?: () => void;
  height?: string;
  width?: string;
  label?: boolean;
  labelBottom?: boolean;
  labelText?: string;
  clickedExternal?: boolean;
  text?: string;
}

const ControlButton: React.FC<ControlButtonProps> = ({ icon, clickedIcon, clickedColor = 'bg-orange-300', backgroundColor = 'bg-stone-900', onClick, height = '33px', width = '33px', label = true, labelBottom = false, labelText = 'Label', clickedExternal = false, text }) => {
  const [isClicked, setIsClicked] = useState(clickedExternal);

  
  const handleClick = () => {
    setIsClicked(!isClicked);
    if (onClick) {
      onClick();
    }
    clickedExternal = !isClicked;
    console.log("clickedExternal", clickedExternal);
  };

  useEffect(() => {
    console.log("clickedExternalChangedExternal", clickedExternal);
    setIsClicked(clickedExternal);
  }, [clickedExternal]);

  return (
    <div className="flex flex-col gap-1 items-center relative">
    <button 
      className={`flex overflow-hidden flex-col justify-center rounded-sm items-center self-stretch my-auto border border-black border-solid ${isClicked ? clickedColor : backgroundColor}`}
      onClick={handleClick}
      style={{ height, width, padding: '18%' }}
    >
      {text ? (
        <span className={`${isClicked ?  'text-black' : 'text-neutral-400'} text-xs`}>{text}</span>
      ) : (
        <img 
          loading="lazy" 
          src={isClicked && clickedIcon ? clickedIcon : icon} 
          alt="" 
          className={`object-contain shrink-0 self-stretch my-auto aspect-square w-[37px] ${isClicked ? 'filter hue-rotate-30' : ''}`} 
        />
      )}
      </button>
      {label && (
        <div className={`label text-xs text-white bg-stone-600 border border-black border-solid w-full absolute ${labelBottom ? 'top-[30px]' : 'bottom-[40px]'} overflow-hidden  `}>
          {labelText}
        </div>
      )}
    </div>
  );
};

export default ControlButton;