import React, { useEffect, useRef, useState } from 'react';
import WaveSurfer from 'wavesurfer.js';
import { useTracksContext } from '../contexts/TracksContext.tsx';

interface AudioTrackProps {
  audioUrl: string;
  trackName: string;
  recordingDate: string;
  isMuted: boolean; 
  volume: number;
  color: string;
  start: number;
  length: number;
  scale: number;
  isPlaying: boolean;
}

const AudioClip: React.FC<AudioTrackProps> = ({ audioUrl, trackName, recordingDate, isMuted, volume, color, start, length, scale, isPlaying }) => {
  const waveformRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const [isReady, setIsReady] = useState(false);
  const { playState, setPlayState, isRecording, setIsRecording, zoomLevel, playbackPosition, seekToPosition } = useTracksContext();

  useEffect(() => {
    if (!waveformRef.current) return;

    const wavesurfer = WaveSurfer.create({
      container: waveformRef.current,
      waveColor: '#000000',
      progressColor: '#000000',
      autoScroll: true,
      height: 40,
      hideScrollbar: true,
      normalize: true,
      interact: true,
      cursorColor: '#ffffff',
      minPxPerSec: zoomLevel,
      barWidth: 2,
      barRadius: 10,
      fillParent: false,
      cursorWidth: 0,
    });

    wavesurfer.load(audioUrl).catch((error) => {
      console.error('Error loading audio:', error);
    });

    wavesurfer.on('ready', () => {
      setIsReady(true);
    });

    wavesurferRef.current = wavesurfer;

    return () => {
      wavesurfer.destroy();
    };
  }, [audioUrl]);

  useEffect(() => {
    if (!wavesurferRef.current || !isReady) return;
    if (seekToPosition === null) return;
    const clipEndTime = length;
    const relativePosition = seekToPosition - start;

    if (relativePosition < 0) {
      wavesurferRef.current.seekTo(0);
    } else if (relativePosition > clipEndTime) {
      wavesurferRef.current.seekTo(1);
    } else {
      const normalizedPosition = relativePosition / clipEndTime;
      wavesurferRef.current.seekTo(normalizedPosition);
    }
  }, [seekToPosition, start, length, isReady]);

  useEffect(() => {
    if (playState && isPlaying) {
      wavesurferRef.current?.play();
    } else {
      wavesurferRef.current?.pause();
    }
  }, [playState, isPlaying]);

  useEffect(() => {
    const newVolume = volume / 20;
    wavesurferRef.current?.setVolume(newVolume);
  }, [volume]);

  useEffect(() => {
    if (isMuted) {
      wavesurferRef.current?.setMuted(true);
    } else {
      wavesurferRef.current?.setMuted(false);
    }
  }, [isMuted]);

  const leftPosition = start * scale;
  const width = length * scale;

  return (
    <div 
      className="rounded-lg h-[calc(100%-10px)] absolute border border-black my-auto" 
      style={{  
        backgroundColor: color,
        left: `${leftPosition}px`,
        width: `${width}px`
      }}
    >
      <div className="text-left pl-2 mb-2 text-xs overflow-hidden whitespace-nowrap text-overflow-ellipsis">
        {trackName} - {recordingDate}
      </div>
      <div ref={waveformRef} />
    </div>
  );    
};

export default AudioClip;
