import React, { useRef, useEffect } from 'react';
import TrackControls from './TrackControls.tsx';
import TrackArea from './TrackArea.tsx';
import PlaybackMarker from './PlaybackMarker.tsx';
import { useTracksContext } from '../contexts/TracksContext.tsx';

interface TrackData {
  name: string;
  color: string;
  recordingDate: string;
  audioUrl: string;
  commentsPageLink: string;
}

const TrackList: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const { setDuration, tracks, zoomLevel, setSeekToPosition } = useTracksContext();

  useEffect(() => {
    // Set initial duration (e.g., 5 minutes)
    setDuration(300);
  }, []);

  const handleTrackAreaClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!scrollContainerRef.current) return;
    
    // Get click position relative to the scroll container
    const rect = scrollContainerRef.current.getBoundingClientRect();
    const scrollLeft = scrollContainerRef.current.scrollLeft;
    const clickX = e.clientX - rect.left + scrollLeft;
    
    // Convert pixel position to time position using zoom level
    const newPosition = clickX / zoomLevel;
    setSeekToPosition(newPosition);
  };

  return (
    <div className="relative" ref={containerRef}>
      <div className="relative">
        <div className="flex">
          {/* Controls Column */}
          <div className="flex flex-col">
            {tracks.map((track, index) => (
              <TrackControls
                key={index}
                trackNumber={index}
              />
            ))}
            <div className="relative border-r-2 border-black border-solid bg-neutral-800 w-[107px] h-[400px] z-0" />
          </div>

          {/* TrackAreas Column with shared scroll */}
          <div
            ref={scrollContainerRef}
            className="flex-grow overflow-x-scroll scrollbar-hidden"
            onClick={handleTrackAreaClick}
          >
            <div className="grid">
              {/* Both elements occupy the same grid cell */}
              <PlaybackMarker
                width={containerRef.current?.clientWidth || 0}
                scale={zoomLevel}
                className="col-start-1 row-start-1"
              />
              <div className="flex flex-col col-start-1 row-start-1">
                {tracks.map((track, index) => (
                  <TrackArea
                    key={index}
                    trackNumber={index}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TrackList;