import React from 'react';
import { useTracksContext } from '../contexts/TracksContext.tsx';

interface TimeRulerProps {
  height?: string;
}

const TimeRuler: React.FC<TimeRulerProps> = ({ height = '24px' }) => {
  const { zoomLevel, duration } = useTracksContext();
  
  // Calculate ruler marks
  const pixelsPerSecond = zoomLevel;
  const totalWidth = 100000;
  const secondsPerMeasure = 16;
  
  const marks: JSX.Element[] = [];
  for (let i = 0; i <= duration; i++) {
    const isMeasure = i % secondsPerMeasure === 0;
    
    marks.push(
      <div
        key={i}
        className="absolute"
        style={{
          left: `${i * pixelsPerSecond}px`,
          height: isMeasure ? '100%' : '50%',
          top: isMeasure ? '0' : '50%',
          width: '1px',
          backgroundColor: isMeasure ? 'white' : '#525252'
        }}
      >
        {isMeasure && (
          <div className="absolute top-1 text-[10px] text-white">
            {`${Math.floor(i / secondsPerMeasure) + 1}`}
          </div>
        )}
      </div>
    );
  }

  return (
    <div 
      className="relative overflow-scroll bg-stone-900 border-b-2 border-black border-solid"
      style={{ height, marginLeft: '107px' }}
    >
      <div className="absolute" style={{ width: `${totalWidth}px` }}>
        {marks}
      </div>
    </div>
  );
};

export default TimeRuler;