import React from 'react';
import Header from './Header.tsx';
import TrackList from './TrackList.tsx';
import AddTrackButton from './AddTrackButton.tsx';
import TimeRuler from './TimeRuler.tsx';
import { useTracksContext } from '../contexts/TracksContext.tsx';

const trackColors = ['#f2e86d','#d7cdcc', '#d3dfb8', '#c0d3e8', '#c5e7e2', '#f6be9a', '#c492b1', '#8cc084'];

const TracksPage: React.FC = () => {
  const { tracks, setTracks } = useTracksContext();

  const handleAddTrack = () => {
    setTracks([...tracks, { 
      name: 'New Track',  
      color: trackColors[tracks.length % trackColors.length], 
      commentsPageLink: '/comments',
      isMuted: false,
      isSolo: false,
      volume: 15,
      clips: [],
      isRecording: false,
      threads: []
    }]);
  };

  return (
    <div className="flex overflow-hidden flex-col mx-auto w-full  border-black border-solid bg-stone-900 max-w-[393px] max-h-[670px]" >
      <Header />
      <TimeRuler />
      <main className="flex-col h-[600px] overflow-y-scroll scrollbar-hidden">
        <TrackList />
      </main>
      <footer className="flex overflow-hidden flex-col items-center px-5 pb-10 max-w-full border-r-2 border-black border-solid bg-neutral-800 w-[107px]">
        <AddTrackButton onClick={handleAddTrack} />
      </footer>
    </div>
  );
};

export default TracksPage;